#!/usr/bin/env python3
"""Path Finder - Samsung PRISM XR Hackathon 2026, Track 3.

IMU-only 6-DoF trajectory estimation for a degraded IMU stream (noise growth, bias drift, spikes, stuck
values, missing rows, duplicated rows, and a zeroed final 5 s after the IMU fails).

Usage:
  python main.py <input.zip | folder | imu0/data.csv> [-o estimated_trajectory.txt]
                 [--weights other_vel.bin] [--no-nn] [--metrics m.json] [--set name=value ...]
                 [--order auto|ag|ga] [--accel-unit auto|ms2|g] [--gyro-unit auto|rad|deg]

Output: TUM format "timestamp tx ty tz qx qy qz qw", exactly one pose per input row, in input order
(duplicated rows and the invalid 5 s blind window included; nothing is appended).

Dependencies: Python 3.9+ and numpy. This file is self-contained: the learned velocity model is embedded at
the end (base64, int8 weights with per-row scales); --weights loads an external float32 file instead.

Pipeline:
  1. Read the CSV (zip / folder / file) into compact arrays; detect column order and units.
     Recordings over 5 minutes are parsed into temp files and memory-mapped, so the heap stays flat.
  2. Flag invalid rows: non-finite, all-zero, out of range, or identical to the previous row (stuck/duplicate).
  3. Initialise roll/pitch and gyro bias from the first static window.
  4. 15-state error-state Kalman filter: midpoint IMU integration, spike repair (1-row lookahead),
     adaptive noise, short gaps bridged by interpolating the IMU, zero-velocity/tilt/zero-rate updates
     when static, a learned body-frame velocity measurement every 0.2 s, and a weak bounded-workspace
     prior (centroid and per-axis spread of the path so far) that limits slow drift.
  5. Long gaps and the blind window after the last valid row: decaying constant-velocity / turn-rate model.
"""
from __future__ import annotations

import io
import json
import math
import os
import sys
import time
import zipfile
from array import array
from collections import deque

import numpy as np

G = 9.81


# ============================================================================ parameters
class Params:
    # validity
    w_max = 35.0            # rad/s
    a_max = 160.0           # m/s^2
    gap_factor = 2.5        # a step longer than gap_factor * nominal dt is not a normal IMU step
    bridge_s = 0.5          # gaps up to this long are bridged by interpolating the IMU (else: motion model)
    bridge_sig_a = 1.0      # m/s^2 extra accel noise on interpolated samples
    bridge_sig_g = 0.05     # rad/s extra gyro noise on interpolated samples
    # spike repair
    spike_k = 10.0
    spike_floor_g = 0.3
    spike_floor_a = 3.0
    # IMU noise (per sample at the nominal rate; the adaptive estimate can only raise these)
    sig_g = 2.5e-3
    sig_a = 3.0e-2
    sig_bg_rw = 2.0e-4
    sig_ba_rw = 3.0e-2
    noise_ema_tau = 1.0
    cov_every = 8           # covariance propagated every N IMU steps (1 = every step; 4/8/16 score the same)
    # initialisation
    init_buf_s = 10.0
    static_win = 40
    init_win = 100
    p0_att = 0.02
    p0_yaw = 1e-4
    p0_v = 0.05
    p0_ba = 0.1
    p0_bg = 0.01
    # static detector + updates
    static_acc_std = 0.10
    static_gyr_mean = 0.04
    static_every = 10
    sig_zupt = 0.02
    sig_tilt = 0.05
    sig_zrate = 0.002
    # gap / blind propagation
    tau_v_gap = 0.5
    tau_w_gap = 0.5
    sig_v_gap = 1.0
    sig_th_gap = 0.2
    tau_v_blind = 0.25      # D-052: 0.5 -> 0.25 (held-out blind ATE)
    tau_w_blind = 1.0
    w_hist_s = 0.5
    v_hist_s = 0.5
    # learned velocity measurement
    nn_sig_scale = 1.0     # predicted std multiplier (EXP-014: 1.0 vs 2.0 on held-out, both column orders)
    nn_sig_floor = 0.10
    nn_every_blocks = 10
    nn_vmax = 6.0
    nn_gate = 16.0          # chi-squared 3-DoF outlier gate on innovation (0 = off)
    # bounded-workspace prior: weak pseudo-measurement "position = start" (0 = off)
    sig_pos = 5.0           # m; sigma while warming up (centre = start), then the upper bound (0 = prior off)
    pos_every = 200         # rows between prior updates (1 s)
    pos_warm = 20           # prior updates before the adaptive prior takes over (D-051: 5 hurt held-out EuRoC)
    pos_adapt = 1.0         # adaptive sigma per axis = pos_adapt * spread of the path so far (0 = keep sig_pos)
    sig_pos_min = 0.3       # m
    # offline RTS smoother over the velocity / position updates (FAQ: offline, future samples allowed; 0 = off)
    smooth = 1
    sm_qv = 0.01            # velocity random walk of the smoother model, m^2/s^3 per axis
    sm_p0 = 0.01            # initial position / velocity variance of the smoother's error state
    sm_v0 = 0.01
    sm_blind = 0            # after the last update: 0 no correction, 1 position offset only, 2 offset + decaying velocity
    sm_centroid = 1         # 1: the smoother's workspace prior uses the centroid of the whole run (non-causal)
    sm_pos_scale = 1.0      # multiplier on the workspace-prior sigma inside the smoother
    la = 1                  # smoother uses the look-ahead velocity model when one is loaded (D-054; 0 = off)
    # platform detection (D-055): rotor vibration separates drones from handheld devices; handheld runs use the
    # hh_* values below instead of the defaults above (-1 = same as the default)
    domain = 0              # 0 auto, 1 force drone, 2 force handheld
    hh_vib = 1.0            # median 1 s accelerometer first-difference RMS, m/s^2: below = handheld
    hh_pos_adapt = 0.6      # D-055: the D-050 prior suits small handheld spaces (TUM-VI), not drone halls
    hh_pos_warm = 5
    hh_sm_pos_scale = -1.0
    hh_sm_blind = -1
    hh_tau_v_blind = -1.0

    def set(self, kv):
        k, v = kv.split("=", 1)
        if not hasattr(Params, k):
            raise SystemExit(f"unknown parameter {k}")
        cur = getattr(Params, k)
        setattr(self, k, type(cur)(float(v)) if isinstance(cur, int) else float(v))


# ============================================================================ input
def _open_text(path):
    """Text stream of the IMU CSV inside a zip, a folder, or the CSV itself."""
    def pick(names):
        imu = [n for n in names if n.replace("\\", "/").lower().endswith("imu0/data.csv")]
        csvs = imu or [n for n in names if n.lower().endswith(".csv")]
        if not csvs:
            raise SystemExit(f"error: no imu0/data.csv (or any .csv) in {path}")
        return sorted(csvs, key=lambda s: (len(s), s))[0]

    if os.path.isdir(path):
        names = []
        for root, _d, files in os.walk(path):
            names += [os.path.join(root, f) for f in files]
        return open(pick(names), "r", encoding="utf-8-sig", errors="replace", newline=None)
    if zipfile.is_zipfile(path):
        zf = zipfile.ZipFile(path)
        name = pick([n for n in zf.namelist() if not n.endswith("/")])
        return io.TextIOWrapper(zf.open(name), encoding="utf-8-sig", errors="replace", newline=None)
    return open(path, "r", encoding="utf-8-sig", errors="replace", newline=None)


def _median(x):
    """Median without np.median (which lazily imports numpy.ma: ~0.6 MB of heap)."""
    x = np.asarray(x)
    m = len(x)
    p = np.partition(x, [(m - 1) // 2, m // 2])
    return 0.5 * (float(p[(m - 1) // 2]) + float(p[m // 2]))


SPILL_ROWS = 60000   # beyond 5 min at 200 Hz the parsed rows go to temp files and are memory-mapped


class Imu:
    """Parsed input. For long recordings V and t_ns are memory-mapped temp files (removed by close())."""
    tmp = ()

    def close(self):
        self.V = self.acc = self.gyr = self.t_ns = None
        for q in self.tmp:
            try:
                os.remove(q)
            except OSError:
                pass


def _open_spill():
    import tempfile
    try:
        fds = [tempfile.mkstemp(prefix="pathfinder_", suffix=".bin") for _ in range(2)]
        return [os.fdopen(fd, "wb") for fd, _ in fds], [q for _, q in fds]
    except OSError:
        return False     # no temp space: stay in RAM


def load(path, order="auto", accel_unit="auto", gyro_unit="auto", spill_rows=SPILL_ROWS):
    """Parse the CSV into int64 ns timestamps and (N,3) gyro [rad/s] / accel [m/s^2] arrays.
    Tolerates a header (with or without '#'), CRLF, ';' / tab / space separators, empty or bad fields (NaN),
    and timestamps in s / ms / us / ns."""
    ts_i = array("q")
    ts_f = None
    vals = array("f")   # float32: the CSV carries 6 decimals, float32 keeps them to ~1e-6 relative
    header = ""
    nan = float("nan")
    rows, spill = 0, None
    with _open_text(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line[0] == "#":
                if not header:
                    header = line
                continue
            if "," in line:
                parts = line.split(",")
            elif ";" in line:
                parts = line.split(";")
            else:
                parts = line.split()
            tok = parts[0].strip()
            try:
                tv = int(tok)
                if ts_f is not None:
                    ts_f.append(float(tv))
                else:
                    ts_i.append(tv)
            except ValueError:
                try:
                    fv = float(tok)
                except ValueError:
                    if not header:
                        header = line
                    continue
                if spill and ts_f is None:
                    ts_i.append(int(round(fv)))   # a float timestamp deep inside an integer file
                else:
                    if ts_f is None:
                        ts_f = array("d", (float(x) for x in ts_i))
                        ts_i = None
                    ts_f.append(fv)
            try:
                row = [float(x) for x in parts[1:7]]
                if len(row) < 6:
                    row += [nan] * (6 - len(row))
            except ValueError:
                row = []
                for x in parts[1:7]:
                    try:
                        row.append(float(x))
                    except ValueError:
                        row.append(nan)
                row += [nan] * (6 - len(row))
            vals.extend(row)
            rows += 1
            if rows % 4096 == 0 and (spill is not None or rows >= spill_rows):
                if spill is None:
                    spill = _open_spill()
                if spill:
                    tcol = ts_i if ts_f is None else ts_f
                    spill[0][0].write(vals.tobytes()); del vals[:]
                    spill[0][1].write(tcol.tobytes()); del tcol[:]
    n = rows
    if n == 0:
        raise SystemExit(f"error: no IMU rows in {path}")
    tmp = ()
    if spill:
        tcol = ts_i if ts_f is None else ts_f
        spill[0][0].write(vals.tobytes()); spill[0][1].write(tcol.tobytes())
        spill[0][0].close(); spill[0][1].close()
        tmp = tuple(spill[1])
        V = np.memmap(tmp[0], np.float32, "r+", shape=(n, 6))
        t_mm = np.memmap(tmp[1], np.int64 if ts_f is None else np.float64, "r", shape=(n,))
    else:
        V = np.frombuffer(vals, dtype=np.float32).reshape(n, 6)
    # --- timestamps -> int64 ns (unit from the median step, like degrade_imu.py)
    if spill:
        t_raw = t_mm
    else:
        t_raw = np.frombuffer(ts_i, np.int64) if ts_f is None else np.frombuffer(ts_f, np.float64)
    d = np.diff(t_raw[: min(n, 4001)])
    d = d[d > 0]
    med = _median(d) if len(d) else None
    if ts_f is None:
        med = 5e6 if med is None else med
        mult = 1 if med >= 1e6 else (1000 if med >= 1e3 else 1_000_000)
        t_ns = t_raw * mult if mult != 1 else t_raw
        ts_unit = {1: "ns", 1000: "us", 1_000_000: "ms"}[mult]
    else:
        med = 5e-3 if med is None else med
        scale, ts_unit = (1e9, "s") if med < 1.0 else ((1e6, "ms") if med < 1e3 else ((1e3, "us") if med < 1e6 else (1.0, "ns")))
        t_ns = np.rint(t_raw * scale).astype(np.int64)
    # --- which triple is the accelerometer
    Vs = V[:: max(1, n // 5000)].astype(np.float64)           # subsample: enough for medians, little memory
    fin = np.all(np.isfinite(Vs), axis=1) & np.any(Vs != 0.0, axis=1)
    Vf = Vs[fin] if fin.any() else Vs
    m1 = _median(np.sqrt((Vf[:, 0:3] ** 2).sum(1))) if len(Vf) else 0.0
    m2 = _median(np.sqrt((Vf[:, 3:6] ** 2).sum(1))) if len(Vf) else 0.0
    h = header.lower()
    hint = None
    ia, ig = min([h.find(k) for k in ("a_rs", "acc") if k in h] or [-1]), min([h.find(k) for k in ("w_rs", "gyr") if k in h] or [-1])
    if ia >= 0 and ig >= 0:
        hint = "ag" if ia < ig else "ga"
    ms2 = lambda m: 6.0 < m < 14.0
    gu = lambda m: 0.6 < m < 1.4
    if order == "auto":
        if ms2(m1) != ms2(m2):
            order = "ag" if ms2(m1) else "ga"
        elif hint:
            order = hint
        elif gu(m1) != gu(m2):
            order = "ag" if gu(m1) else "ga"
        else:
            order = "ga"  # EuRoC layout
    acc, gyr = (V[:, 0:3], V[:, 3:6]) if order == "ag" else (V[:, 3:6], V[:, 0:3])
    ma, mg = (m1, m2) if order == "ag" else (m2, m1)
    if accel_unit == "g" or (accel_unit == "auto" and gu(ma)):
        acc *= np.float32(G)
        accel_unit = "g"
    else:
        accel_unit = "m/s^2"
    if gyro_unit == "deg" or (gyro_unit == "auto" and mg > 8.0):
        gyr *= np.float32(math.pi / 180.0)
        gyro_unit = "deg/s"
    else:
        gyro_unit = "rad/s"
    imu = Imu()
    imu.tmp = tmp
    imu.n, imu.t_ns, imu.V, imu.acc, imu.gyr = n, t_ns, V, acc, gyr
    imu.gi = 3 if order == "ag" else 0        # column of the first gyro value in V (accel at 3 - gi)
    imu.info = dict(rows=n, out_of_core=bool(spill), order=order, header_hint=hint, timestamp_unit=ts_unit, accel_unit=accel_unit,
                    gyro_unit=gyro_unit)
    return imu


def validity(imu, P):
    """Row is valid unless non-finite, all zero, out of range, or identical to the previous row (stuck or
    duplicated sample). Computed in chunks so no full-size temporaries are allocated."""
    n, V = imu.n, imu.V
    lim = np.empty(6, np.float32)
    lim[imu.gi:imu.gi + 3], lim[3 - imu.gi:6 - imu.gi] = P.w_max, P.a_max
    ok = np.zeros(n, bool)
    CH = 4096
    for c0 in range(0, n, CH):
        c1 = min(n, c0 + CH)
        X = V[c0:c1]
        with np.errstate(invalid="ignore"):
            o = np.all(np.abs(X) <= lim, axis=1)          # NaN compares False -> invalid
        o &= np.any(X != 0.0, axis=1)
        if c0 > 0:
            o &= ~np.all(V[c0 - 1:c1 - 1] == X, axis=1)
        else:
            o[1:] &= ~np.all(V[0:c1 - 1] == X[1:], axis=1)
        ok[c0:c1] = o
    return ok


# ============================================================================ rotations (scalar)
def qmul(a, b):
    aw, ax, ay, az = a
    bw, bx, by, bz = b
    return (aw * bw - ax * bx - ay * by - az * bz, aw * bx + ax * bw + ay * bz - az * by,
            aw * by - ax * bz + ay * bw + az * bx, aw * bz + ax * by - ay * bx + az * bw)


def qexp(x, y, z):
    ang = math.sqrt(x * x + y * y + z * z)
    if ang < 1e-12:
        return qnorm((1.0, 0.5 * x, 0.5 * y, 0.5 * z))
    s = math.sin(0.5 * ang) / ang
    return (math.cos(0.5 * ang), x * s, y * s, z * s)


def qnorm(q):
    w, x, y, z = q
    n = math.sqrt(w * w + x * x + y * y + z * z)
    return (w / n, x / n, y / n, z / n)


def qrot(q):
    w, x, y, z = q
    return ((1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y)),
            (2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x)),
            (2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)))


def gravity_to_quat(f):
    roll = math.atan2(f[1], f[2])
    pitch = math.atan2(-f[0], math.sqrt(f[1] ** 2 + f[2] ** 2))
    cr, sr, cp, sp = math.cos(roll / 2), math.sin(roll / 2), math.cos(pitch / 2), math.sin(pitch / 2)
    return (cp * cr, cp * sr, sp * cr, -sp * sr)


def lerp(a, b, u):
    return [a[0] + u * (b[0] - a[0]), a[1] + u * (b[1] - a[1]), a[2] + u * (b[2] - a[2])]


def skew(v):
    return np.array([[0.0, -v[2], v[1]], [v[2], 0.0, -v[0]], [-v[1], v[0], 0.0]])


# ============================================================================ initialisation
def initialise(imu, valid, P):
    t, n = imu.t_ns, imu.n
    m0 = min(n, 8000)                                    # the first init_buf_s seconds are inside these rows
    vi = np.nonzero(valid[:m0])[0]
    d = np.diff(t[: min(n, 2001)])
    d = d[d > 0]
    dt_ns = int(_median(d)) if len(d) else 5_000_000
    last_valid = n - 1 - int(np.argmax(valid[::-1])) if valid.any() else -1
    q0, bg0, static_init = None, (0.0, 0.0, 0.0), False
    if len(vi):
        b = vi[t[vi] <= t[0] + int(P.init_buf_s * 1e9)]
        gb, ab = imu.gyr[b], imu.acc[b]
        W = P.init_win
        for k in range(0, len(b) - W + 1, W // 4):
            an = np.sqrt((ab[k:k + W] ** 2).sum(1))
            gm = gb[k:k + W].mean(0)
            gn = np.sqrt(((gb[k:k + W] - gm) ** 2).sum(1))
            if an.std() < P.static_acc_std and gn.mean() < P.static_gyr_mean and abs(an.mean() - G) < 0.5:
                q0 = gravity_to_quat(ab[k:k + W].mean(0))
                bg0 = tuple(float(x) for x in gm)
                static_init = True
                break
        if q0 is None and len(b):
            q0 = gravity_to_quat(ab.mean(0))
    if q0 is None:
        q0 = (1.0, 0.0, 0.0, 0.0)
    return dt_ns, last_valid, q0, bg0, static_init


# ============================================================================ learned velocity model
NN_T, NN_F, NN_IN, NN_H1, NN_H2, NN_OUT = 50, 9, 450, 256, 128, 6
NN_SA, NN_SG = 0.2, 0.5


class VelNet:
    """Ensemble of MLPs (450-256-128-6). Output: mean body velocity and log(mean predicted variance +
    variance between members).

    Weights are held as int8 with one float32 scale per output row (w ~ scale * q); biases are float32.
    That is a quarter of the float32 size, and int8 -> float32 widening per call is cheap. A float32 weight
    file (--weights) is quantised the same way on load, so both paths give identical results."""

    LAYERS = ((NN_H1, NN_IN), (NN_H2, NN_H1), (NN_OUT, NN_H2))

    @staticmethod
    def quantise(w):
        scale = (np.abs(w).max(axis=1) / 127.0).astype(np.float32)
        scale[scale == 0] = 1.0
        return scale, np.rint(w / scale[:, None]).astype(np.int8)

    def __init__(self, path=None, embedded=None):
        self.layers = []                      # per member: [(scale, q, bias) x 3]
        if path is None:                      # embedded: per layer scale (f32), q (int8), bias (f32)
            import base64
            members, b64 = embedded or (_EMB_MEMBERS, _EMB_B64)
            blob = base64.b64decode(b64)      # one bytes constant (adjacent literals are joined at compile time)
            o = 0
            for _ in range(members):
                mem = []
                for r, c in self.LAYERS:
                    sc = np.frombuffer(blob, np.float32, r, o); o += 4 * r
                    q = np.frombuffer(blob, np.int8, r * c, o).reshape(r, c); o += r * c
                    b = np.frombuffer(blob, np.float32, r, o); o += 4 * r
                    mem.append((sc, q, b))
                self.layers.append(mem)
            if o != len(blob):
                raise ValueError("embedded weights: size mismatch")
        else:                                 # flat float32 file: per layer W (r x c) then bias (r)
            per = sum(r * c + r for r, c in self.LAYERS)
            size = os.path.getsize(path)
            if size == 0 or size % (4 * per):
                raise ValueError(f"{path}: unexpected size")
            with open(path, "rb") as fh:      # layer by layer: never more than one float32 layer in RAM
                for _ in range(size // (4 * per)):
                    mem = []
                    for r, c in self.LAYERS:
                        w = np.fromfile(fh, np.float32, r * c).reshape(r, c)
                        b = np.fromfile(fh, np.float32, r)
                        mem.append(self.quantise(w) + (b,))
                    self.layers.append(mem)
        self.k = len(self.layers)

    def forward(self, x):
        mean = np.zeros(3); sq = np.zeros(3); var = np.zeros(3)
        for (s1, q1, b1), (s2, q2, b2), (s3, q3, b3) in self.layers:
            h = q1.astype(np.float32) @ x
            h *= s1; h += b1
            np.maximum(h, 0, out=h)
            h = q2.astype(np.float32) @ h
            h *= s2; h += b2
            np.maximum(h, 0, out=h)
            o = ((q3.astype(np.float32) @ h) * s3 + b3).astype(np.float64)
            mean += o[:3]; sq += o[:3] ** 2; var += np.exp(o[3:])
        mean /= self.k; var /= self.k
        between = np.maximum(0.0, sq / self.k - mean ** 2)
        return mean, np.log(var + between)


# ============================================================================ filter
IP, IV, ITH, IBA, IBG = 0, 3, 6, 9, 12
I3 = np.eye(3)
_D = np.arange(3)
D_V, D_TH, D_BA, D_BG = IV + _D, ITH + _D, IBA + _D, IBG + _D   # diagonal indices of each 3-state block


class ESKF:
    def __init__(self, q0, bg0, P, static_init):
        self.prm = P
        self.p = [0.0, 0.0, 0.0]; self.v = [0.0, 0.0, 0.0]; self.q = q0
        self.ba = [0.0, 0.0, 0.0]; self.bg = list(bg0)
        d = np.zeros(15)
        d[IP:IP + 3] = 1e-6
        d[IV:IV + 3] = (P.p0_v if static_init else 1.0) ** 2
        d[ITH:ITH + 2] = P.p0_att ** 2; d[ITH + 2] = P.p0_yaw ** 2
        d[IBA:IBA + 3] = P.p0_ba ** 2; d[IBG:IBG + 3] = P.p0_bg ** 2
        self.P = np.diag(d)
        self.F = np.eye(15)          # IMU-block transition (only its non-identity blocks are rewritten)
        self.Fg = np.eye(15)         # gap transition
        self.R, self.Rq = qrot(q0), q0   # rotation matrix of the attitude object self.Rq
        self._reset_block()
        self.log = None              # EventLog for the offline smoother (None = off)
        self.row = 0                 # current input row, set by the main loop (for the log)

    # ---- deferred covariance propagation over a block of IMU steps
    def _reset_block(self):
        self.b_n = 0; self.b_dt = 0.0
        self.b_ab = [0.0, 0.0, 0.0]; self.b_w = [0.0, 0.0, 0.0]
        self.b_qa = 0.0; self.b_qg = 0.0; self.b_R0 = None

    def flush(self):
        if self.b_n == 0:
            return
        dt = self.b_dt
        ab = [x / dt for x in self.b_ab]
        R0 = np.array(self.b_R0)
        RA = R0 @ skew(ab)
        F = self.F
        F[IP:IP + 3, IV:IV + 3] = I3 * dt
        F[IP:IP + 3, ITH:ITH + 3] = -0.5 * dt * dt * RA
        F[IP:IP + 3, IBA:IBA + 3] = -0.5 * dt * dt * R0
        F[IV:IV + 3, ITH:ITH + 3] = -dt * RA
        F[IV:IV + 3, IBA:IBA + 3] = -dt * R0
        F[ITH:ITH + 3, ITH:ITH + 3] = np.array(qrot(qexp(*self.b_w))).T
        F[ITH:ITH + 3, IBG:IBG + 3] = -dt * I3
        Pm = F @ self.P @ F.T
        prm = self.prm
        Pm[D_V, D_V] += self.b_qa
        Pm[D_TH, D_TH] += self.b_qg
        Pm[D_BA, D_BA] += prm.sig_ba_rw ** 2 * dt
        Pm[D_BG, D_BG] += prm.sig_bg_rw ** 2 * dt
        self.P = Pm
        self._reset_block()

    def imu_step(self, g0, a0, g1, a1, dt, sig_g, sig_a):
        """Midpoint integration of one IMU interval; covariance deferred to flush()."""
        bg, ba, q = self.bg, self.ba, self.q
        R0 = self.R if self.Rq is q else qrot(q)     # usually R1 of the previous step
        wx = 0.5 * (g0[0] + g1[0]) - bg[0]
        wy = 0.5 * (g0[1] + g1[1]) - bg[1]
        wz = 0.5 * (g0[2] + g1[2]) - bg[2]
        q1 = qnorm(qmul(q, qexp(wx * dt, wy * dt, wz * dt)))
        R1 = qrot(q1)
        a0x, a0y, a0z = a0[0] - ba[0], a0[1] - ba[1], a0[2] - ba[2]
        a1x, a1y, a1z = a1[0] - ba[0], a1[1] - ba[1], a1[2] - ba[2]
        aW = [0.5 * (R0[r][0] * a0x + R0[r][1] * a0y + R0[r][2] * a0z + R1[r][0] * a1x + R1[r][1] * a1y + R1[r][2] * a1z)
              for r in range(3)]
        aW[2] -= G
        p, v = self.p, self.v
        h = 0.5 * dt * dt
        for r in range(3):
            p[r] += v[r] * dt + aW[r] * h
            v[r] += aW[r] * dt
        self.q = self.Rq = q1
        self.R = R1
        if self.b_n == 0:
            self.b_R0 = R0
        self.b_n += 1
        self.b_dt += dt
        bab, bw = self.b_ab, self.b_w
        bab[0] += 0.5 * (a0x + a1x) * dt; bab[1] += 0.5 * (a0y + a1y) * dt; bab[2] += 0.5 * (a0z + a1z) * dt
        bw[0] += wx * dt; bw[1] += wy * dt; bw[2] += wz * dt
        self.b_qa += (sig_a * dt) ** 2
        self.b_qg += (sig_g * dt) ** 2
        if self.b_n >= self.prm.cov_every:
            self.flush()

    def gap_step(self, w, dt, tau_v, sig_v, sig_th):
        self.flush()
        dv = math.exp(-dt / tau_v)
        p, v = self.p, self.v
        for r in range(3):
            p[r] += v[r] * dt
            v[r] *= dv
        self.q = qnorm(qmul(self.q, qexp(w[0] * dt, w[1] * dt, w[2] * dt)))
        F = self.Fg
        F[IP:IP + 3, IV:IV + 3] = I3 * dt
        F[IV:IV + 3, IV:IV + 3] = I3 * dv
        Pm = F @ self.P @ F.T
        prm = self.prm
        Pm[D_V, D_V] += sig_v * sig_v * dt
        Pm[D_TH, D_TH] += sig_th * sig_th * dt
        Pm[D_BA, D_BA] += prm.sig_ba_rw ** 2 * dt
        Pm[D_BG, D_BG] += prm.sig_bg_rw ** 2 * dt
        self.P = Pm

    def update(self, H, r, sig):
        self.flush()
        P = self.P
        Rm = I3 * (sig * sig)
        PHt = P @ H.T
        S = H @ PHt + Rm
        K = PHt @ np.linalg.inv(S)
        dx = K @ r
        IKH = np.eye(15) - K @ H
        P = IKH @ P @ IKH.T + K @ Rm @ K.T
        self.P = 0.5 * (P + P.T)
        self._correct(dx)

    def update_block(self, idx, r, sig):
        """Update for a direct measurement of the 3 error states starting at `idx` (H selects them), in the same
        Joseph form as update() but on slices: no H matrix, a third of the matrix products."""
        self.flush()
        P = self.P
        Rm = I3 * (sig * sig)                                 # sig: scalar or one value per axis
        PHt = P[:, idx:idx + 3]
        K = PHt @ np.linalg.inv(PHt[idx:idx + 3] + Rm)
        dx = K @ r
        A = P - K @ P[idx:idx + 3]                            # (I - KH) P
        P = A - A[:, idx:idx + 3] @ K.T + K @ Rm @ K.T
        self.P = 0.5 * (P + P.T)
        self._correct(dx)

    def _correct(self, dx):
        dx = dx.tolist()
        for i in range(3):
            self.p[i] += dx[IP + i]
            self.v[i] += dx[IV + i]
            self.ba[i] += dx[IBA + i]
            self.bg[i] += dx[IBG + i]
        self.q = qnorm(qmul(self.q, qexp(dx[ITH], dx[ITH + 1], dx[ITH + 2])))

    def update_velocity(self, vw, sig, gate=0.0):
        r = np.array([vw[i] - self.v[i] for i in range(3)])
        if gate > 0.0:
            self.flush()
            P_vv = self.P[IV:IV + 3, IV:IV + 3]
            S = P_vv + I3 * (sig * sig)
            try:
                d2 = float(r @ np.linalg.solve(S, r))
                if d2 > gate:
                    sig = sig * math.sqrt(d2 / gate)
            except np.linalg.LinAlgError:
                pass
        if self.log is None:
            self.update_block(IV, r, sig)
            return
        pre = (*self.p, *self.v)
        self.update_block(IV, r, sig)
        self.log.add(self.row, 0, vw, sig, pre, self.p, self.v)

    def update_position(self, pw, sig):
        if self.log is None:
            self.update_block(IP, np.array([pw[i] - self.p[i] for i in range(3)]), sig)
            return
        pre = (*self.p, *self.v)
        self.update_block(IP, np.array([pw[i] - self.p[i] for i in range(3)]), sig)
        self.log.add(self.row, 1, pw, sig, pre, self.p, self.v)

    def static_updates(self, a_mean, g_mean):
        prm = self.prm
        self.update_velocity((0.0, 0.0, 0.0), prm.sig_zupt)
        R = qrot(self.q)
        fb = [R[2][c] * G for c in range(3)]  # R^T [0,0,G]
        H = np.zeros((3, 15)); H[:, ITH:ITH + 3] = skew(fb); H[:, IBA:IBA + 3] = I3
        self.update(H, np.array([a_mean[i] - (self.ba[i] + fb[i]) for i in range(3)]), prm.sig_tilt)
        self.update_block(IBG, np.array([g_mean[i] - self.bg[i] for i in range(3)]), prm.sig_zrate)

    def checkpoint(self):
        return (list(self.p), list(self.v), self.q)

    def restore(self, cp):
        """Back to a checkpoint after a non-finite state; the covariance restarts from identity."""
        self.p, self.v, self.q = list(cp[0]), list(cp[1]), cp[2]
        self.P = np.eye(15)
        self._reset_block()

    def finite(self):
        p, v, q = self.p, self.v, self.q
        # a non-finite covariance reaches the state at the next update, so checking the state is enough
        return math.isfinite(p[0] + p[1] + p[2] + v[0] + v[1] + v[2] + q[0] + q[1] + q[2] + q[3])


# ============================================================================ offline smoother
class EventLog:
    """Every velocity / position update of the forward filter: row, kind (0 velocity, 1 position), measurement,
    sigma per axis, and the filter's position + velocity just before and just after it. 160 bytes per event
    (about 6 events per second), kept in a flat array of doubles."""
    W = 20

    def __init__(self):
        self.a = array("d")

    def add(self, row, kind, z, sig, pre, p, v):
        s = sig if hasattr(sig, "__len__") else (sig, sig, sig)
        self.a.extend((row, kind, z[0], z[1], z[2], s[0], s[1], s[2], *pre, p[0], p[1], p[2], v[0], v[1], v[2]))

    def __len__(self):
        return len(self.a) // self.W

    def set_meas(self, k, z, sig):
        """Replace event k's measurement (the look-ahead velocity for that instant, D-054)."""
        o = k * self.W
        self.a[o + 2], self.a[o + 3], self.a[o + 4] = z[0], z[1], z[2]
        self.a[o + 5] = self.a[o + 6] = self.a[o + 7] = sig


def rts_offsets(log, t_ns, P):
    """Fixed-interval (RTS) smoother over the logged updates.

    Model, per world axis: the error of the forward filter's [position, velocity], e = x - x_filter, propagates as
    e' = F e (F = [[1, dt], [0, 1]]) plus a velocity random walk; between two updates the IMU motion is the filter's
    own (it cancels in e). Each logged update is replayed as a measurement, so a forward pass of this small filter
    reproduces the forward filter, and the backward RTS pass lets every learned-velocity and prior update also correct
    the path before it. Returns, per event, the smoothed position correction just after it (post) and just before
    it (prior), the velocity correction at the last event, and the event rows."""
    m = len(log)
    if m == 0:
        return None
    E = np.frombuffer(log.a, dtype=np.float64).reshape(m, EventLog.W)
    rows = E[:, 0].astype(np.int64)
    ts = (np.asarray(t_ns[rows], dtype=np.int64) - int(t_ns[0])) * 1e-9
    kind, z, s = E[:, 1], E[:, 2:5], E[:, 5:8]
    pre_p, pre_v, post_p, post_v = E[:, 8:11], E[:, 11:14], E[:, 14:17], E[:, 17:20]
    qv = P.sm_qv
    pos = kind == 1
    if pos.any():
        s = s.copy(); z = z.copy()
        s[pos] *= P.sm_pos_scale
        if P.sm_centroid:
            z[pos] = post_p[pos].mean(0)
    ep, ev = np.zeros(3), np.zeros(3)
    Ppp, Ppv, Pvv = np.full(3, P.sm_p0), np.zeros(3), np.full(3, P.sm_v0)
    Fe = np.empty((m, 2, 3))          # filtered error, post-update, relative to the filter's post-update state
    FP = np.empty((m, 3, 3))          # filtered covariance (pp, pv, vv)
    for k in range(m):
        if k:
            dt = ts[k] - ts[k - 1]
            ep = ep + dt * ev
            Ppp, Ppv, Pvv = Ppp + 2 * dt * Ppv + dt * dt * Pvv, Ppv + dt * Pvv, Pvv + qv * dt
        s2 = s[k] * s[k]
        if kind[k] == 0:
            r = z[k] - (pre_v[k] + ev)
            S = Pvv + s2
            Kp, Kv = Ppv / S, Pvv / S
            Ppp, Ppv, Pvv = Ppp - Kp * Ppv, Ppv - Kp * Pvv, Pvv - Kv * Pvv
        else:
            r = z[k] - (pre_p[k] + ep)
            S = Ppp + s2
            Kp, Kv = Ppp / S, Ppv / S
            Ppp, Ppv, Pvv = Ppp - Kp * Ppp, Ppv - Kp * Ppv, Pvv - Kv * Ppv
        ep = ep + Kp * r + pre_p[k] - post_p[k]
        ev = ev + Kv * r + pre_v[k] - post_v[k]
        Fe[k, 0], Fe[k, 1] = ep, ev
        FP[k, 0], FP[k, 1], FP[k, 2] = Ppp, Ppv, Pvv
    # backward pass (Fe is overwritten with the smoothed error)
    for k in range(m - 2, -1, -1):
        dt = ts[k + 1] - ts[k]
        Ppp, Ppv, Pvv = FP[k, 0], FP[k, 1], FP[k, 2]
        a = Ppp + 2 * dt * Ppv + dt * dt * Pvv + 1e-12
        b = Ppv + dt * Pvv
        c = Pvv + qv * dt + 1e-12
        det = a * c - b * b
        m00, m01, m10, m11 = Ppp + dt * Ppv, Ppv, Ppv + dt * Pvv, Pvv      # P F^T
        c00, c01 = (m00 * c - m01 * b) / det, (m01 * a - m00 * b) / det
        c10, c11 = (m10 * c - m11 * b) / det, (m11 * a - m10 * b) / det
        tp = Fe[k + 1, 0] + post_p[k + 1] - pre_p[k + 1]                 # smoothed, relative to the prior state
        tv = Fe[k + 1, 1] + post_v[k + 1] - pre_v[k + 1]
        dp = tp - (Fe[k, 0] + dt * Fe[k, 1])
        dv = tv - Fe[k, 1]
        Fe[k, 0] = Fe[k, 0] + c00 * dp + c01 * dv
        Fe[k, 1] = Fe[k, 1] + c10 * dp + c11 * dv
    d_post = Fe[:, 0].copy()
    d_prior = Fe[:, 0] + post_p - pre_p
    # several events on one row: the row's pose is after the last one, the gap before it ends at the first one
    last = np.r_[rows[1:] != rows[:-1], True]
    first = np.r_[True, rows[1:] != rows[:-1]]
    return rows[last], d_post[last], d_prior[first], Fe[-1, 1].copy()


class PoseBuf:
    """Forward-pass poses (float32 x, y, z, qw, qx, qy, qz; 28 bytes per row), memory-mapped for long inputs."""

    def __init__(self, n, spill_rows):
        self.tmp = None
        if n > spill_rows:
            import tempfile
            try:
                fd, self.tmp = tempfile.mkstemp(prefix="pathfinder_", suffix=".pose")
                os.close(fd)
                self.a = np.memmap(self.tmp, np.float32, "w+", shape=(n, 7))
                return
            except OSError:
                self.tmp = None
        self.a = np.empty((n, 7), np.float32)

    def put(self, i, p, q):
        self.a[i] = (p[0], p[1], p[2], q[0], q[1], q[2], q[3])

    def close(self):
        self.a = None
        if self.tmp:
            try:
                os.remove(self.tmp)
            except OSError:
                pass


def write_poses(out_path, buf, t_ns, sm, tau_blind, mode=2):
    """Write every pose, adding the smoother's position correction (linear in time between events; after the last
    event the velocity correction decays like the blind-window velocity)."""
    wr = Writer(out_path)
    n = len(buf.a)
    CH = 4096
    if sm is not None:
        rows, d_post, d_prior, dv_last = sm
        t_ev = (np.asarray(t_ns[rows], dtype=np.int64) - int(t_ns[0])) * 1e-9
    for c0 in range(0, n, CH):
        c1 = min(n, c0 + CH)
        blk = np.asarray(buf.a[c0:c1], dtype=np.float64)
        if sm is not None:
            idx = np.arange(c0, c1)
            tt = (np.asarray(t_ns[c0:c1], dtype=np.int64) - int(t_ns[0])) * 1e-9
            j = np.searchsorted(rows, idx, "right") - 1          # last event at or before the row
            d = np.empty((c1 - c0, 3))
            before = j < 0
            d[before] = d_prior[0]
            after = j >= len(rows) - 1
            if after.any():
                dt = np.maximum(0.0, tt[after] - t_ev[-1])
                if mode == 2:
                    d[after] = d_post[-1] + np.outer(tau_blind * (1 - np.exp(-dt / tau_blind)), dv_last)
                else:
                    d[after] = d_post[-1] if mode == 1 else 0.0
            mid = ~before & ~after
            if mid.any():
                jm = j[mid]
                on = rows[jm] == idx[mid]
                span = t_ev[jm + 1] - t_ev[jm]
                u = np.where(span > 0, (tt[mid] - t_ev[jm]) / np.where(span > 0, span, 1.0), 0.0)
                dm = d_post[jm] + u[:, None] * (d_prior[jm + 1] - d_post[jm])
                dm[on] = d_post[jm[on]]
                d[mid] = dm
            blk[:, 0:3] += d
        for k in range(c1 - c0):
            b = blk[k]
            wr.emit(int(t_ns[c0 + k]), (b[0], b[1], b[2]), (b[3], b[4], b[5], b[6]))
    wr.close()
    return wr.count


# ============================================================================ output
class Writer:
    def __init__(self, path):
        self.f = open(path, "w", newline="\n")
        self.f.write("# timestamp tx ty tz qx qy qz qw\n")
        self.buf = []
        self.last = None
        self.count = 0

    def emit(self, t_ns, p, q):
        w, x, y, z = q
        n = math.sqrt(w * w + x * x + y * y + z * z)
        w, x, y, z = w / n, x / n, y / n, z / n
        l = self.last
        if l is not None and w * l[0] + x * l[1] + y * l[2] + z * l[3] < 0:
            w, x, y, z = -w, -x, -y, -z
        self.last = (w, x, y, z)
        s, fr = divmod(t_ns, 1_000_000_000)
        self.buf.append(f"{s}.{fr:09d} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f} {x:.9f} {y:.9f} {z:.9f} {w:.9f}\n")
        self.count += 1
        if len(self.buf) >= 512:
            self.f.write("".join(self.buf))
            self.buf.clear()

    def close(self):
        self.f.write("".join(self.buf))
        self.buf.clear()
        self.f.close()


# ============================================================================ main loop
def run(in_path, out_path, P=None, net=None, order="auto", accel_unit="auto", gyro_unit="auto",
        spill_rows=SPILL_ROWS, la_net=None):
    imu = load(in_path, order, accel_unit, gyro_unit, spill_rows)
    try:
        return _run(imu, out_path, P or Params(), net, spill_rows, la_net)
    finally:
        imu.close()


def vibration(imu, valid_a, win=200):
    """Median over 1 s windows of the RMS first difference of the accelerometer (valid neighbours only).
    Drone rotors make it 2-4 m/s^2; a handheld device stays below 1 (D-055). Chunked, so memory stays flat."""
    n = imu.n
    vals = []
    CH = 50 * win
    for c0 in range(0, max(0, n - 1), CH):
        c1 = min(n, c0 + CH + 1)
        a = np.asarray(imu.acc[c0:c1], dtype=np.float64)
        ok = valid_a[c0:c1]
        e = ((a[1:] - a[:-1]) ** 2).sum(1)
        good = ok[1:] & ok[:-1]
        for w0 in range(0, len(e) - win + 1, win):
            g = good[w0:w0 + win]
            if g.sum() > win // 2:
                vals.append(float(e[w0:w0 + win][g].mean()))
    return math.sqrt(float(np.median(vals))) if vals else float("nan")


def apply_domain(imu, valid_a, P):
    """Pick drone / handheld settings. Returns (params to use, vibration, 'drone' | 'handheld')."""
    vib = vibration(imu, valid_a)
    hand = P.domain == 2 or (P.domain == 0 and math.isfinite(vib) and vib < P.hh_vib)
    if not hand:
        return P, vib, "drone"
    import copy
    Q = copy.copy(P)
    for k in ("pos_adapt", "pos_warm", "sm_pos_scale", "sm_blind", "tau_v_blind"):
        v = getattr(P, "hh_" + k)
        if v >= 0:
            setattr(Q, k, type(getattr(P, k))(v))
    return Q, vib, "handheld"


def _run(imu, out_path, P, net, spill_rows=SPILL_ROWS, la_net=None):
    n, t_all = imu.n, imu.t_ns
    valid_a = validity(imu, P)
    P, vib, domain = apply_domain(imu, valid_a, P)
    dt_ns, last_valid, q0, bg0, static_init = initialise(imu, valid_a, P)
    blind_start = last_valid + 1
    # next valid row index for every row (n if none)
    nxt_valid_a = np.arange(n, dtype=np.int32)
    nxt_valid_a[~valid_a] = n
    np.minimum.accumulate(nxt_valid_a[::-1], out=nxt_valid_a[::-1])

    f = ESKF(q0, bg0, P, static_init)
    if P.smooth:
        f.log = EventLog()
    buf = PoseBuf(n, spill_rows)
    dt_nom = dt_ns * 1e-9
    gap_dt = P.gap_factor * dt_nom
    alpha = 1.0 - math.exp(-dt_nom / P.noise_ema_tau)
    var_g, var_a = P.sig_g ** 2, P.sig_a ** 2
    var_g_min, var_a_min = var_g, var_a
    bridge_ns = int(P.bridge_s * 1e9)
    qa_br, qg_br = P.bridge_sig_a ** 2, P.bridge_sig_g ** 2

    w_hist_n = max(1, int(round(P.w_hist_s / dt_nom)))
    w_hist = deque()
    w_sum = [0.0, 0.0, 0.0]
    w_gap = [0.0, 0.0, 0.0]
    in_gap = False
    v_hist_n = max(1, int(round(P.v_hist_s / dt_nom)))
    v_hist = deque()
    v_sum = [0.0, 0.0, 0.0]
    # static window (real samples only): |a| running sums + raw samples
    SW = P.static_win
    win = deque()
    s_an = 0.0; s_an2 = 0.0
    static_count = 0
    # learned velocity window
    use_nn = net is not None
    nn_blocks = np.zeros((NN_T, NN_F), np.float32)
    nn_nb = 0; nn_ns = 0; nn_since = 0
    nn_acc = [0.0] * NN_F
    # look-ahead velocity for the smoother (D-054): the window's attitude per block, and the logged causal
    # update of each of the last la_ticks + 1 ticks
    la_ticks = la_net.lag // (4 * P.nn_every_blocks) if (la_net is not None and use_nn and f.log is not None
                                                         and P.la) else 0
    la_blk = NN_T - 1 - (la_net.lag // 4 if la_ticks else 0)
    nn_q = deque(maxlen=NN_T)
    la_ev = deque(maxlen=la_ticks + 1)

    have_last = False          # last real valid sample (for spikes and bridging)
    last_g = last_a = None; t_last = 0
    anc_g = anc_a = None       # integration anchor (real or interpolated sample at t_anc)
    t_anc = 0
    good = f.checkpoint()
    on_n = 0; on_s = [0.0, 0.0, 0.0]; on_s2 = [0.0, 0.0, 0.0]
    st = dict(valid_rows=int(valid_a.sum()), bridged_rows=0, gap_rows=0, blind_rows=max(0, n - blind_start),
              nn_updates=0, static_updates=0, la_updates=0)

    def w_mean():
        k = len(w_hist)
        return [w_sum[c] / k for c in range(3)] if k else [0.0, 0.0, 0.0]

    def v_mean():
        k = len(v_hist)
        return [v_sum[c] / k for c in range(3)] if k else list(f.v)

    def coast(dt, tau_w, tau_v):
        """No usable IMU: decay the turn rate and the velocity (blind window and long gaps)."""
        nonlocal w_gap
        e = math.exp(-dt / tau_w)
        w_gap = [x * e for x in w_gap]
        f.gap_step(w_gap, dt, tau_v, P.sig_v_gap, P.sig_th_gap)

    def reset_windows():
        nonlocal s_an, s_an2, static_count, nn_nb, nn_ns, nn_since
        win.clear(); s_an = 0.0; s_an2 = 0.0; static_count = 0
        nn_nb = 0; nn_ns = 0; nn_since = 0
        for k in range(NN_F):
            nn_acc[k] = 0.0
        nn_q.clear(); la_ev.clear()

    def feed_nn(g1, a1):
        nonlocal nn_nb, nn_ns, nn_since
        q = f.q
        w, x, y, z = q
        gb = (2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y))
        acc = nn_acc
        acc[0] += a1[0] * NN_SA; acc[1] += a1[1] * NN_SA; acc[2] += a1[2] * NN_SA
        acc[3] += g1[0] * NN_SG; acc[4] += g1[1] * NN_SG; acc[5] += g1[2] * NN_SG
        acc[6] += gb[0]; acc[7] += gb[1]; acc[8] += gb[2]
        nn_ns += 1
        if nn_ns < 4:
            return
        nn_ns = 0
        if nn_nb == NN_T:
            nn_blocks[:-1] = nn_blocks[1:]
        else:
            nn_nb += 1
        nn_blocks[nn_nb - 1] = [x_ / 4.0 for x_ in acc]
        if la_ticks:
            nn_q.append(q)
        for k in range(NN_F):
            acc[k] = 0.0
        if nn_nb == NN_T:
            nn_since += 1
            if nn_since >= P.nn_every_blocks:
                nn_since = 0
                vb, lv = net.forward(nn_blocks.reshape(-1))
                if math.sqrt(float(vb @ vb)) < P.nn_vmax:
                    var = float(np.exp(lv).mean())
                    sig = max(P.nn_sig_floor, P.nn_sig_scale * math.sqrt(var))
                    R = qrot(q)
                    vw = [R[r][0] * vb[0] + R[r][1] * vb[1] + R[r][2] * vb[2] for r in range(3)]
                    f.update_velocity(vw, sig, P.nn_gate)
                    st["nn_updates"] += 1
                    k_ev = len(f.log) - 1 if f.log is not None else -1
                else:
                    k_ev = -1
                if la_ticks:
                    la_ev.append(k_ev)
                    if len(la_ev) == la_ticks + 1 and la_ev[0] >= 0:
                        vb2, lv2 = la_net.forward(nn_blocks.reshape(-1))
                        if math.sqrt(float(vb2 @ vb2)) < P.nn_vmax:
                            sig2 = max(P.nn_sig_floor, P.nn_sig_scale * math.sqrt(float(np.exp(lv2).mean())))
                            R2 = qrot(nn_q[la_blk])
                            vw2 = [R2[r][0] * vb2[0] + R2[r][1] * vb2[1] + R2[r][2] * vb2[2] for r in range(3)]
                            f.log.set_meas(la_ev[0], vw2, sig2)
                            st["la_updates"] += 1

    def integrate_to(t1, g1, a1, interp):
        """Integrate from the anchor to (t1, g1, a1), in sub-steps of about one nominal dt when the interval
        is longer (interpolating the IMU linearly). Feeds the learned window with every sub-step sample."""
        nonlocal anc_g, anc_a, t_anc
        span = (t1 - t_anc) * 1e-9
        m = max(1, int(round(span / dt_nom)))
        sg, sa = math.sqrt(var_g), math.sqrt(var_a)
        if interp or span > gap_dt:
            sg = math.sqrt(var_g + qg_br); sa = math.sqrt(var_a + qa_br)
        h = span / m
        g0, a0 = anc_g, anc_a
        for k in range(1, m + 1):
            if k == m:
                gk, ak = g1, a1
            else:
                gk, ak = lerp(anc_g, g1, k / m), lerp(anc_a, a1, k / m)
            f.imu_step(g0, a0, gk, ak, h, sg, sa)
            if use_nn:
                feed_nn(gk, ak)
            g0, a0 = gk, ak
        anc_g, anc_a, t_anc = g1, a1, t1

    CH = 1024
    V = imu.V
    gi = imu.gi
    ai = 3 - gi
    t_prev = 0
    for c0 in range(0, n, CH):
        c1 = min(n, c0 + CH + 1)  # one row of overlap for the lookahead
        rows = V[c0:c1].tolist()
        ts = t_all[c0:c1].tolist()
        vl = valid_a[c0:c1].tolist()
        nv = nxt_valid_a[c0:min(n, c0 + CH)].tolist()
        for k in range(min(CH, n - c0)):
            i = c0 + k
            f.row = i
            r = rows[k]
            t = ts[k]
            valid = vl[k]
            g1 = r[gi:gi + 3]
            a1 = r[ai:ai + 3]
            # ---- spike repair with one row of lookahead (both neighbours valid)
            if valid and have_last and i + 1 < n and vl[k + 1]:
                rn = rows[k + 1]
                for x, xp, xn, var, floor in ((g1, last_g, rn[gi:gi + 3], var_g, P.spike_floor_g),
                                              (a1, last_a, rn[ai:ai + 3], var_a, P.spike_floor_a)):
                    T = max(P.spike_k * math.sqrt(var), floor)
                    for ch in range(3):
                        if abs(x[ch] - xp[ch]) > T and abs(x[ch] - xn[ch]) > T and abs(xn[ch] - xp[ch]) < 0.5 * T:
                            x[ch] = 0.5 * (xp[ch] + xn[ch])
            if i == 0:
                if valid:
                    last_g, last_a, t_last, have_last = g1, a1, t, True
                    anc_g, anc_a, t_anc = g1, a1, t
                buf.put(i, f.p, f.q)
                t_prev = t
                continue
            dt = (t - t_prev) * 1e-9
            t_prev = t
            if i >= blind_start:
                # ---- blind window: the IMU has failed
                if i == blind_start:
                    w_gap = w_mean()
                    f.v = v_mean()
                if dt > 0:
                    coast(dt, P.tau_w_blind, P.tau_v_blind)
                buf.put(i, f.p, f.q)
                continue
            if dt <= 0:
                buf.put(i, f.p, f.q)   # duplicated / non-increasing timestamp: same pose
                continue
            bridged = False
            if have_last and not in_gap:
                if valid and (t - t_anc) * 1e-9 <= gap_dt and t_anc == t_last:
                    # normal IMU step; adaptive noise from first differences (var(diff) = 2 sigma^2)
                    dg = (g1[0] - last_g[0]) ** 2 + (g1[1] - last_g[1]) ** 2 + (g1[2] - last_g[2]) ** 2
                    da = (a1[0] - last_a[0]) ** 2 + (a1[1] - last_a[1]) ** 2 + (a1[2] - last_a[2]) ** 2
                    var_g = max(var_g_min, (1 - alpha) * var_g + alpha * dg / 6.0)
                    var_a = max(var_a_min, (1 - alpha) * var_a + alpha * da / 6.0)
                    integrate_to(t, g1, a1, False)
                    bridged = True
                elif valid and t - t_last <= bridge_ns:
                    integrate_to(t, g1, a1, False)     # valid row after missing / stuck rows
                    bridged = True
                    st["bridged_rows"] += 1
                elif not valid:
                    j = nv[k]
                    if j < blind_start and int(t_all[j]) - t_last <= bridge_ns:
                        tj = int(t_all[j])
                        rj = V[j].tolist()
                        u = (t - t_last) / (tj - t_last)
                        gk, ak = lerp(last_g, rj[gi:gi + 3], u), lerp(last_a, rj[ai:ai + 3], u)
                        integrate_to(t, gk, ak, True)  # invalid row inside a short gap: interpolated IMU
                        bridged = True
                        st["bridged_rows"] += 1
            if not bridged:
                # ---- long gap: motion model (decaying velocity and turn rate)
                st["gap_rows"] += 1
                if not in_gap:
                    w_gap = w_mean()
                    in_gap = True
                coast(dt, P.tau_w_gap, P.tau_v_gap)
                if valid:
                    in_gap = False
                    reset_windows()
                    anc_g, anc_a, t_anc = g1, a1, t
                    if use_nn:
                        feed_nn(g1, a1)
            if valid:
                last_g, last_a, t_last, have_last = g1, a1, t, True
                bg = f.bg
                wc = (g1[0] - bg[0], g1[1] - bg[1], g1[2] - bg[2])
                w_hist.append(wc)
                w_sum[0] += wc[0]; w_sum[1] += wc[1]; w_sum[2] += wc[2]
                if len(w_hist) > w_hist_n:
                    o = w_hist.popleft()
                    w_sum[0] -= o[0]; w_sum[1] -= o[1]; w_sum[2] -= o[2]
                vc = tuple(f.v)
                v_hist.append(vc)
                v_sum[0] += vc[0]; v_sum[1] += vc[1]; v_sum[2] += vc[2]
                if len(v_hist) > v_hist_n:
                    ov = v_hist.popleft()
                    v_sum[0] -= ov[0]; v_sum[1] -= ov[1]; v_sum[2] -= ov[2]
                # static detector over the last SW real samples
                an = math.sqrt(a1[0] * a1[0] + a1[1] * a1[1] + a1[2] * a1[2]) - G
                win.append((g1, a1, an))
                s_an += an; s_an2 += an * an
                if len(win) > SW:
                    o = win.popleft()
                    s_an -= o[2]; s_an2 -= o[2] * o[2]
                if len(win) == SW:
                    mu = s_an / SW
                    is_static = False
                    if math.sqrt(max(0.0, s_an2 / SW - mu * mu)) < P.static_acc_std:
                        gm = 0.0
                        for (gg, _aa, _n) in win:
                            gm += math.sqrt((gg[0] - bg[0]) ** 2 + (gg[1] - bg[1]) ** 2 + (gg[2] - bg[2]) ** 2)
                        is_static = gm / SW < P.static_gyr_mean
                    if is_static:
                        static_count += 1
                        if static_count % P.static_every == 0:
                            am = [sum(s[1][c] for s in win) / SW for c in range(3)]
                            gmn = [sum(s[0][c] for s in win) / SW for c in range(3)]
                            f.static_updates(am, gmn)
                            st["static_updates"] += 1
                    else:
                        static_count = 0
                if P.sig_pos > 0 and i % P.pos_every == 0:
                    # bounded-workspace prior: the path so far says where the device lives (centroid) and
                    # how large the space is (spread per axis); pull weakly towards that
                    on_n += 1
                    for c in range(3):
                        on_s[c] += f.p[c]; on_s2[c] += f.p[c] * f.p[c]
                    if on_n >= P.pos_warm and P.pos_adapt > 0:
                        mu = [on_s[c] / on_n for c in range(3)]
                        sd = np.sqrt(np.maximum(0.0, np.array(on_s2) / on_n - np.array(mu) ** 2))
                        f.update_position(mu, np.clip(P.pos_adapt * sd, P.sig_pos_min, P.sig_pos))
                    else:
                        f.update_position((0.0, 0.0, 0.0), P.sig_pos)
            if not f.finite():
                f.restore(good)
            else:
                good = f.checkpoint()
            buf.put(i, f.p, f.q)
    try:
        sm = rts_offsets(f.log, t_all, P) if f.log is not None else None
        st["smoother_events"] = len(f.log) if f.log is not None else 0
        f.log = None
        count = write_poses(out_path, buf, t_all, sm, P.tau_v_blind, P.sm_blind)
    finally:
        buf.close()
    st.update(imu.info)
    st.update(poses=count, imu_seconds=(int(t_all[-1]) - int(t_all[0])) * 1e-9 if n > 1 else 0.0,
              static_init=static_init, nn=net is not None, dt_ns=dt_ns, vibration=vib, domain=domain)
    return st


# ============================================================================ CLI
def load_la(path=None, lag=None):
    """Look-ahead ensemble for the smoother: the embedded one, or a float32 file with its lag. None if absent."""
    try:
        if path:
            net = VelNet(path)
            net.lag = int(lag or 0)
        elif _LA_MEMBERS:
            net = VelNet(None, (_LA_MEMBERS, _LA_B64))
            net.lag = _LA_LAG
        else:
            return None
    except (OSError, ValueError) as e:
        print(f"warning: look-ahead model not loaded ({e})", file=sys.stderr)
        return None
    return net if net.lag > 0 and net.lag % 40 == 0 and net.lag // 4 < NN_T else None


def main(argv):
    import argparse
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("input")
    ap.add_argument("-o", "--output", default="estimated_trajectory.txt")
    ap.add_argument("--weights", help="external float32 weight file (default: the ensemble embedded in this file)")
    ap.add_argument("--no-nn", action="store_true")
    ap.add_argument("--la-weights", help="external float32 look-ahead ensemble (default: the embedded one)")
    ap.add_argument("--la-lag", type=int, help="look-ahead lag in samples for --la-weights (multiple of 40)")
    ap.add_argument("--metrics")
    ap.add_argument("--set", action="append", default=[], metavar="NAME=VALUE")
    ap.add_argument("--order", choices=["auto", "ag", "ga"], default="auto", help="ag: accel first, ga: gyro first")
    ap.add_argument("--accel-unit", choices=["auto", "ms2", "g"], default="auto")
    ap.add_argument("--gyro-unit", choices=["auto", "rad", "deg"], default="auto")
    a = ap.parse_args(argv)
    P = Params()
    for kv in a.set:
        P.set(kv)
    t0 = time.process_time()
    net = None
    if not a.no_nn:
        try:
            net = VelNet(a.weights)
        except (OSError, ValueError) as e:
            print(f"warning: learned velocity model not loaded ({e}); running the physics-only filter", file=sys.stderr)
    la_net = load_la(a.la_weights, a.la_lag) if net is not None else None
    st = run(a.input, a.output, P, net, a.order, a.accel_unit, a.gyro_unit, la_net=la_net)
    cpu = time.process_time() - t0
    st["cpu_s"] = cpu
    st["ms_per_imu_second"] = 1000.0 * cpu / st["imu_seconds"] if st["imu_seconds"] > 0 else float("nan")
    print(f"wrote {st['poses']} poses for {st['rows']} rows to {a.output} "
          f"({st['ms_per_imu_second']:.2f} ms per IMU-second, order {st['order']}, nn {'on' if net else 'off'})",
          file=sys.stderr)
    if a.metrics:
        with open(a.metrics, "w") as fo:
            json.dump(st, fo, indent=1)
    return 0


